using System.Globalization; using System.Web; using System.Web.UI; using SMC.BhoomiMalmatta.Models.Dto; namespace SMC.BhoomiMalmatta.Web.Department.Controls { public partial class OfficerKpiCards : UserControl { public void Bind(OfficerDashboardCounts c) { phCards.Controls.Clear(); if(c==null)return; Add("▤","एकूण अर्ज","सर्व संबंधित अर्ज",c.Total,"blue","total","all"); Add("◷","प्रलंबित अर्ज","कार्यवाही प्रलंबित",c.Pending,"orange","pending","mine"); Add("➜","प्रक्रिया केलेले / पुढे पाठवलेले","आपली कार्यवाही पूर्ण",c.Processed,"purple","processed","processed"); Add("✓","मंजूर अर्ज","अंतिम मंजूर अर्ज",c.Approved,"green","approved","approved"); Add("×","नाकारलेले अर्ज","नाकारलेले अर्ज",c.Rejected,"red","rejected","rejected"); } private void Add(string icon,string title,string note,int n,string color,string key,string view){var href="Applications.aspx?view="+HttpUtility.UrlEncode(view);phCards.Controls.Add(new LiteralControl("<a class=\"officer-kpi-link\" href=\""+HttpUtility.HtmlAttributeEncode(href)+"\"><div class=\"officer-kpi\" data-kpi=\""+key+"\"><span class=\"kpi-icon "+color+"\">"+HttpUtility.HtmlEncode(icon)+"</span><div class=\"kpi-copy\"><span>"+HttpUtility.HtmlEncode(title)+"</span><strong>"+n.ToString(CultureInfo.InvariantCulture)+"</strong><small>"+HttpUtility.HtmlEncode(note)+"</small></div></div></a>"));} } }
